function assert(condition,message){if(!condition)throw new Error(message);}
function test(name,callback){try{callback();console.log(`✓ ${name}`);}catch(error){console.error(`✗ ${name}: ${error.message}`);throw error;}}

test("faux mur : passage vers le niveau 2 et retour",()=>{const manager=new LevelManager(424242),one=manager.ensure(1),two=manager.ensure(2),transitions=new TransitionManager(),exitX=one.originX+(one.maze.exitColumn+.5)*one.maze.cellSize,entryX=two.originX+(two.maze.entryColumn+.5)*two.maze.cellSize;transitions.registerAnchor({id:"hidden-exit",level:1,position:{x:exitX,y:0,z:one.bounds.maxZ},yaw:0,width:one.maze.cellSize,height:3.25,depth:1.2});transitions.registerAnchor({id:"return-wall",level:2,position:{x:entryX,y:0,z:two.bounds.minZ},yaw:0,width:two.maze.cellSize,height:3.25,depth:1.2});transitions.register(getLevelConfig(1).transitions[0]);const forward=transitions.tryCrossing({levelNumber:1,previousPosition:{x:exitX,y:1.7,z:one.bounds.maxZ-1},currentPosition:{x:exitX,y:1.7,z:one.bounds.maxZ+.2},isEnabled:()=>true});assert(forward?.targetLevel===2,"aller absent");transitions.releaseExitedAnchors(2,{x:entryX,y:1.7,z:two.bounds.minZ+2});const back=transitions.tryCrossing({levelNumber:2,previousPosition:{x:entryX,y:1.7,z:two.bounds.minZ+1},currentPosition:{x:entryX,y:1.7,z:two.bounds.minZ-.2},isEnabled:()=>true});assert(back?.targetLevel===1,"retour absent");});

test("porte physique : niveau 2 vers 3 et retour",()=>{const manager=new LevelManager(525252),two=manager.ensure(2),three=manager.ensure(3),x=two.originX+(two.maze.exitColumn+.5)*two.maze.cellSize,z=two.bounds.maxZ;assert(Math.abs(z-three.bounds.minZ)<1e-9,"sols désalignés");assert(manager.findByPosition(x,z-.01)?.levelNumber===2,"côté niveau 2 absent");assert(manager.findByPosition(x,z+.01)?.levelNumber===3,"côté niveau 3 absent");});

test("porte : contraste, ouverture, fermeture et sécurité en mouvement",()=>{const assembly=createDoorAssembly({width:2,height:2}),controller=new DoorController(assembly,{maxAngle:Math.PI/2,duration:1000,playerRadius:.15}),panelColor=assembly.doorPanel.material.color,frameColor=assembly.leftPost.material.color,contrast=Math.hypot(panelColor.r-frameColor.r,panelColor.g-frameColor.g,panelColor.b-frameColor.b);assert(panelColor.getHex()===0xe7e3d5,"panneau de porte non blanc");assert(contrast>.55,"cadre insuffisamment contrasté");controller.open(0);controller.update(1000,{x:5,z:5});assert(!controller.moving&&controller.angle===controller.maxAngle,"ouverture incomplète");controller.close(1100);controller.update(2100,{x:5,z:5});assert(controller.angle===0,"fermeture incomplète");controller.open(2200);controller.update(2700,{x:-.292893,z:.707107});assert(controller.blocked&&!controller.moving,"joueur traversé");assembly.dispose();});

test("porte : mur de tête raccordé au plafond sans collision basse",()=>{const material=new THREE.MeshStandardMaterial(),head=createDoorHeadWall({width:2.35,openingHeight:2.48,wallHeight:3.25,depth:.13,material}),size=new THREE.Vector3(),epsilon=1e-6;head.geometry.computeBoundingBox();head.geometry.boundingBox.getSize(size);assert(Math.abs(size.y-.77)<epsilon,"hauteur de remplissage incorrecte");assert(Math.abs(head.position.y+size.y/2-3.25)<epsilon,"remplissage non raccordé au plafond");assert(Math.abs(head.position.y-size.y/2-2.48)<epsilon,"remplissage non raccordé au linteau");assert(head.userData.nonBlocking===true,"mur de tête ajouté aux collisions basses");head.geometry.dispose();material.dispose();});

test("objet : inventaire et état persistants",()=>{const item=createItem("water_bottle",{userData:{instanceId:"test-water",level:1,container:createWaterBottleContainer(0)}}),inventory=[item],manager=new LevelManager(626262);item.userData.name="BOUTEILLE VIDE";for(let level=1;level<=8;level++){manager.setActive(level);manager.streamingWindow();}assert(inventory[0]===item&&inventory[0].userData.container.units===0,"inventaire modifié");const restored=restoreItem(snapshotItem(item));assert(restored.userData.instanceId==="test-water"&&restored.userData.container.units===0,"état au sol perdu");disposeObjectTree(item);disposeObjectTree(restored);});

test("lapin et pile : identités séparées, charge conservée et cycle irréversible",()=>{const plush=createItem("plush",{userData:{instanceId:"rabbit-1"}}),battery=createItem("battery",{userData:{instanceId:"battery-1"}}),installed=installBatteryInPlush(plush.userData,battery.userData);assert(installed.powerState===PLUSH_POWER_STATES.BATTERY_INSTALLED&&installed.containedBattery.instanceId==="battery-1","identité de pile perdue à l’installation");assert(installed.containedBattery.energy.charge===BATTERY_DEFAULT_CAPACITY,"charge initiale incorrecte");const powered=powerPlush(installed),burnt=burnOutPlush(powered.data);assert(powered.changed&&burnt.changed&&burnt.data.powerState===PLUSH_POWER_STATES.FRIED,"cycle d’activation incomplet");assert(burnt.remainingCharge===BATTERY_DEFAULT_CAPACITY-PLUSH_ACTIVATION_COST&&burnt.remainingCharge>0,"pile vidée par le lapin");assert(!powerPlush(burnt.data).changed,"lapin grillé rallumable");Object.assign(plush.userData,burnt.data);const restored=restoreItem(snapshotItem(plush));assert(restored.userData.containedBattery.instanceId==="battery-1"&&restored.userData.containedBattery.energy.charge===burnt.remainingCharge,"pile contenue non persistée");const legacy=normalizePlushPowerData({instanceId:"old-rabbit",powered:true,fried:true});assert(legacy.powerState===PLUSH_POWER_STATES.FRIED&&legacy.containedBattery.instanceId==="embedded-battery:old-rabbit","ancien lapin non normalisé");disposeObjectTree(plush);disposeObjectTree(battery);disposeObjectTree(restored);});

test("lapin grillé au sol : apparence lisible, persistance et guide unique",()=>{const plush=createItem("plush",{userData:{instanceId:"rabbit-ground",fried:true,powered:true,guideTriggered:true}});applyFriedPlushAppearance(plush);const fur=plush.children.find(child=>child.userData.plushPart==="fur"),indicator=plush.children.find(child=>child.userData.burntIndicator);assert(fur.material.color.getHex()===0x705548&&fur.material.color.getHex()!==0x222222,"lapin encore noir ou non brûlé");assert(indicator?.isPointLight&&indicator.intensity<1,"œil grillé trop lumineux ou absent");const restored=restoreItem(snapshotItem(plush));assert(restored.userData.instanceId==="rabbit-ground"&&restored.userData.guideTriggered&&restored.children.some(child=>child.userData.burntIndicator),"lapin au sol mal restauré");const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(source.includes("plush.userData.fried&&!plush.userData.guideTriggered")&&source.includes("plush.userData.guideTriggered=true"),"guide redéclenchable");assert(!source.includes("plush.userData.consumed=true")&&!source.includes("disposeObjectTree(plush)"),"lapin encore consommé après dépôt");disposeObjectTree(plush);disposeObjectTree(restored);});

test("extraction de pile : une seule restitution, même identité et charge inconnue",()=>{setLocale("fr",{persist:false});const plush=createItem("plush",{userData:{instanceId:"rabbit-extract"}}),battery=createItem("battery",{userData:{instanceId:"battery-extract"}}),installed=installBatteryInPlush(plush.userData,battery.userData),burnt=burnOutPlush(powerPlush(installed).data),extracted=extractBatteryFromPlush(burnt.data);assert(extracted.changed&&extracted.battery.instanceId==="battery-extract","mauvaise pile extraite");assert(extracted.battery.energy.charge===BATTERY_DEFAULT_CAPACITY-PLUSH_ACTIVATION_COST,"charge restante modifiée à l’extraction");assert(extracted.data.fried&&!extracted.data.powered&&extracted.data.batteryExtracted&&!extracted.data.containedBattery,"compartiment non vidé");assert(!extractBatteryFromPlush(extracted.data).changed,"seconde extraction autorisée");Object.assign(plush.userData,extracted.data);const recovered=createItem("battery",{userData:{...extracted.battery,recoveredFromPlush:true}}),restoredPlush=restoreItem(snapshotItem(plush)),restoredBattery=restoreItem(snapshotItem(recovered));assert(restoredPlush.userData.batteryExtracted&&!restoredPlush.userData.containedBattery&&restoredBattery.userData.instanceId==="battery-extract","extraction non persistée");assert(restoredBattery.userData.description.includes("difficile")&&!restoredBattery.userData.description.includes(String(extracted.battery.energy.charge)),"charge exacte révélée ou description absente");const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(source.includes('t("game.action.extractBattery")')&&source.includes('markSave("extract-battery")')&&source.includes('recordResource("battery","extracted"'),"interaction d’extraction non branchée");disposeObjectTree(plush);disposeObjectTree(battery);disposeObjectTree(recovered);disposeObjectTree(restoredPlush);disposeObjectTree(restoredBattery);});

test("alimentation générique : compatibilité, consommation, retrait et lampe simulée",()=>{const flashlight=createPowerSlot({acceptedKinds:[POWER_SOURCE_KINDS.AA_BATTERY]}),battery={type:"battery",instanceId:"flashlight-cell",powerSource:{kind:POWER_SOURCE_KINDS.AA_BATTERY,capacity:100,charge:65}},wrong={instanceId:"wrong-cell",kind:"battery-9v",capacity:100,charge:100};assert(canInstallPowerSource(flashlight,battery)&&!canInstallPowerSource(flashlight,wrong),"compatibilité de source incorrecte");assert(!installPowerSource(flashlight,wrong).changed&&installPowerSource(flashlight,wrong).reason==="incompatible","source incompatible acceptée");const installed=installPowerSource(flashlight,battery),used=consumePowerSource(installed.slot,40),removed=removePowerSource(used.slot);assert(installed.changed&&used.consumed===40&&used.slot.source.charge===25,"consommation de lampe incorrecte");assert(powerLevel(used.slot.source)===POWER_LEVELS.WEAK,"niveau qualitatif incorrect");assert(removed.changed&&removed.source.instanceId==="flashlight-cell"&&removed.source.charge===25&&!removed.slot.source,"identité ou charge perdue au retrait");const fixed=installPowerSource(createPowerSlot({acceptedKinds:[POWER_SOURCE_KINDS.AA_BATTERY],removable:false}),battery);assert(!removePowerSource(fixed.slot).changed,"source fixe retirée");const depleted=consumePowerSource(installed.slot,999);assert(depleted.slot.source.charge===0&&powerLevel(depleted.slot.source)===POWER_LEVELS.EMPTY,"épuisement non borné");const plushSource=readFileSync(new URL("../js/systems/item-power-state.js",import.meta.url),"utf8");for(const operation of["installPowerSource","consumePowerSource","removePowerSource"])assert(plushSource.includes(operation),`lapin non branché au contrat : ${operation}`);});

test("contenants à unités : normalisation, consommation, ajout et bornes",()=>{const bottle=createUnitContainer({capacity:4,units:2,unitKind:UNIT_KINDS.WATER_DOSE,reloadable:true,containerKind:CONTAINER_KINDS.BOTTLE});assert(bottle.capacity===4&&bottle.units===2&&hasUnits(bottle,2)&&!hasUnits(bottle,3),"bouteille normalisée incorrectement");const drunk=consumeUnits(bottle,1);assert(drunk.changed&&drunk.consumed===1&&drunk.container.units===1&&bottle.units===2,"consommation mutable ou incorrecte");const emptied=removeUnits(drunk.container,8);assert(emptied.removed===1&&emptied.container.units===0&&!removeUnits(emptied.container,1).changed,"retrait non borné");const refilled=addUnits(emptied.container,99);assert(refilled.added===4&&refilled.container.units===4,"remplissage non borné");const blister=createUnitContainer({capacity:8,units:3,unitKind:UNIT_KINDS.MEDICINE_TABLET,reloadable:false,containerKind:CONTAINER_KINDS.BLISTER});assert(!addUnits(blister,1).changed&&addUnits(blister,1).reason==="not-reloadable","plaquette rechargeable");const malformed=normalizeUnitContainer({capacity:-4,units:99,unitKind:""});assert(malformed.capacity===1&&malformed.units===1&&malformed.unitKind==="generic-unit","valeurs invalides non corrigées");assert(Object.isFrozen(bottle)&&Object.isFrozen(drunk.container),"états de contenant mutables");});

test("migration bouteilles : type unique, doses et identités conservés",()=>{const full=createItem("water_full",{userData:{instanceId:"legacy-full",level:1,sips:3}}),half=createItem("water_half",{userData:{instanceId:"legacy-half",level:2,sips:1}}),empty=createItem("water_empty",{userData:{instanceId:"legacy-empty",level:2,sips:0}}),level=createEmptyLevelSave();level.objects=[snapshotItem(half),snapshotItem(empty)];const save=createExplorationSave({seed:1818,inventory:[snapshotItem(full)],levels:{2:level}}),migration=reconcileUnitContainers(save),items=[...migration.save.inventory,...migration.save.levels[2].objects];assert(migration.diagnostics.normalized===3&&items.every(item=>item.type===WATER_BOTTLE_TYPE),"anciens types non remplacés");assert(items.map(item=>item.userData.container.units).join(",")==="3,1,0","gorgées perdues pendant la migration");assert(items.map(item=>item.userData.instanceId).join(",")==="legacy-full,legacy-half,legacy-empty","identités remplacées");assert(items.every(item=>item.userData.container.capacity===4&&item.userData.container.reloadable&&item.userData.container.unitKind===UNIT_KINDS.WATER_DOSE),"contrat de bouteille incorrect");const again=reconcileUnitContainers(migration.save);assert(JSON.stringify(again.save)===JSON.stringify(migration.save),"migration des bouteilles non idempotente");const rules=expandObjectRules(getLevelConfig(1).objects).filter(rule=>rule.type===WATER_BOTTLE_TYPE);assert(rules.length===2&&new Set(rules.map(rule=>rule.instanceId)).size===2&&rules.map(rule=>rule.userData.container.units).join(",")==="4,2","placements du niveau 1 non configurés");[full,half,empty].forEach(disposeObjectTree);});

test("transfert d’unités : compatibilité, politiques et conservation",()=>{const reservoir=createUnitContainer({capacity:8,units:6,unitKind:UNIT_KINDS.WATER_DOSE,reloadable:true}),bottle=createWaterBottleContainer(1),moved=transferUnits(reservoir,bottle,2,{sourceId:"source",targetId:"bottle"});assert(moved.changed&&moved.reason==="transferred"&&moved.transferred===2,"transfert compatible refusé");assert(moved.source.units===4&&moved.target.units===3&&reservoir.units+bottle.units===moved.source.units+moved.target.units,"unités créées ou perdues");assert(reservoir.units===6&&bottle.units===1,"état source modifié");const medicine=createUnitContainer({capacity:8,units:4,unitKind:UNIT_KINDS.MEDICINE_TABLET,reloadable:false,containerKind:CONTAINER_KINDS.BLISTER}),magazine=createUnitContainer({capacity:12,units:2,unitKind:UNIT_KINDS.AMMUNITION_9MM,reloadable:true,containerKind:CONTAINER_KINDS.MAGAZINE}),wrongAmmo=createUnitContainer({capacity:10,units:5,unitKind:"ammunition-45",reloadable:true,containerKind:CONTAINER_KINDS.MAGAZINE});assert(!unitKindsCompatible(medicine,bottle)&&!transferUnits(medicine,bottle,1).changed&&transferUnits(medicine,bottle,1).reason==="incompatible","ressource incompatible acceptée");assert(transferUnits(reservoir,medicine,1).reason==="not-reloadable","plaquette rechargée");assert(transferUnits(wrongAmmo,magazine,1).reason==="incompatible","munition incompatible acceptée");assert(inspectUnitTransfer(reservoir,bottle,-1).reason==="invalid-amount","quantité négative acceptée");assert(transferUnits(reservoir,createWaterBottleContainer(3),2).reason==="capacity-exceeded","surcharge partielle autorisée");assert(transferUnits(createWaterBottleContainer(1,8),createWaterBottleContainer(0),2).reason==="insufficient-units","source insuffisante ignorée");assert(transferUnits(reservoir,bottle,1,{sourceId:"same",targetId:"same"}).reason==="same-container","auto-transfert duplicateur accepté");});

test("consommables spécialisés : eau, soif et comprimés restent distincts",()=>{const bottle=createWaterBottleContainer(2),drink=drinkWaterDose(bottle,{thirst:42,relief:15});assert(drink.changed&&drink.reason==="drank"&&drink.container.units===1&&drink.thirst===27,"effet de la gorgée incorrect");const last=drinkWaterDose(drink.container,{thirst:7}),empty=drinkWaterDose(last.container,{thirst:last.thirst});assert(last.container.units===0&&last.thirst===0&&!empty.changed&&empty.reason==="empty","bouteille vide ou soif mal bornée");const blister=createMedicineBlister({capacity:6,tablets:2,medicineKind:MEDICINE_KINDS.ANALGESIC}),tablet=takeMedicineDose(blister);assert(tablet.changed&&tablet.reason==="medicine-taken"&&tablet.container.units===1&&blister.units===2,"prise de comprimé incorrecte ou mutable");assert(!blister.reloadable&&takeMedicineDose(bottle).reason==="not-medicine"&&drinkWaterDose(blister,{thirst:50}).reason==="not-water","comportements de consommables mélangés");const object=createItem("medicine_blister",{userData:{instanceId:"med-a"}});assert(object.userData.container.containerKind===CONTAINER_KINDS.BLISTER&&object.userData.nameKey==="item.medicineBlister.name","objet médical non enregistré ou traduit");const gameSource=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(gameSource.includes("drinkWaterDose(object.userData.container,{thirst})"),"bouteille encore reliée directement au noyau quantitatif");disposeObjectTree(object);});

test("arme : chargeur, chambre, tir et rechargement restent cohérents",()=>{const pistol=createPistol({instanceId:"sidearm"}),magazine=createMagazine({instanceId:"mag-a",rounds:3}),inserted=insertMagazine(pistol,magazine);assert(inserted.changed&&inserted.firearm.magazine.instanceId==="mag-a"&&!pistol.magazine,"insertion mutable ou absente");const chambered=chamberRound(inserted.firearm);assert(chambered.changed&&chambered.firearm.chambered&&chambered.firearm.magazine.container.units===2,"chambrage incorrect");const fired=firePistol(chambered.firearm);assert(fired.fired&&fired.autoChambered&&fired.firearm.chambered&&fired.firearm.magazine.container.units===1,"cycle semi-automatique incorrect");const replacement=createMagazine({instanceId:"mag-b",rounds:5}),reloaded=reloadPistol(fired.firearm,replacement);assert(reloaded.changed&&reloaded.reason==="magazine-replaced"&&reloaded.ejectedMagazine.instanceId==="mag-a"&&reloaded.firearm.magazine.instanceId==="mag-b","changement de chargeur incomplet");const removed=removeMagazine(reloaded.firearm);assert(removed.changed&&removed.magazine.instanceId==="mag-b"&&!removed.firearm.magazine&&removed.firearm.chambered,"retrait du chargeur a perdu la cartouche chambrée");const shot=firePistol(removed.firearm);assert(shot.fired&&!shot.autoChambered&&!shot.firearm.chambered,"dernier tir sans chargeur incorrect");const wrong=createMagazine({instanceId:"wrong",caliber:"45",rounds:4});assert(insertMagazine(pistol,wrong).reason==="incompatible-magazine"&&!reloadPistol(reloaded.firearm,wrong).changed,"calibre incompatible accepté");assert(!firePistol(pistol).changed&&firePistol(pistol).reason==="not-chambered","tir à vide accepté");const magazineObject=createItem("magazine_9mm",{userData:{instanceId:"object-mag"}}),pistolObject=createItem("pistol_9mm",{userData:{instanceId:"object-gun"}});assert(magazineObject.userData.container.unitKind===UNIT_KINDS.AMMUNITION_9MM&&pistolObject.userData.firearm.instanceId==="object-gun"&&pistolObject.userData.nameKey==="item.pistol9mm.name","objets d’arme non enregistrés ou identité perdue");disposeObjectTree(magazineObject);disposeObjectTree(pistolObject);});

test("indicateur d’unités : cases, jauge, texte et traductions",()=>{const four=createUnitIndicatorModel(createWaterBottleContainer(3)),eight=createUnitIndicatorModel(createWaterBottleContainer(0,8)),bar=createUnitIndicatorModel(createUnitContainer({capacity:12,units:5})),text=createUnitIndicatorModel(createUnitContainer({capacity:64,units:64}));assert(four.mode===UNIT_INDICATOR_MODES.CELLS&&four.state==="partial"&&four.ratio===.75,"indicateur quatre cases incorrect");assert(eight.mode===UNIT_INDICATOR_MODES.CELLS&&eight.state==="empty","indicateur huit cases incorrect");assert(bar.mode===UNIT_INDICATOR_MODES.BAR&&bar.units===5&&text.mode===UNIT_INDICATOR_MODES.TEXT&&text.state==="full","repli jauge ou texte incorrect");for(const locale of["fr","en"]){setLocale(locale,{persist:false});for(const key of["unit.indicator.label","unit.state.empty","unit.state.partial","unit.state.full","unit.action.refilled","unit.error.incompatible","unit.error.notReloadable","unit.error.capacityExceeded","unit.error.insufficientUnits","unit.error.sameContainer","unit.error.invalidAmount"])assert(translate(key,{units:2,capacity:4})!==key,`traduction d’unité absente en ${locale} : ${key}`);}setLocale("fr",{persist:false});});

