test("InputManager : maintien, pression unique, tactile, pause et nettoyage",()=>{class Target{constructor(){this.handlers=new Map();}addEventListener(type,handler){const handlers=this.handlers.get(type)??new Set();handlers.add(handler);this.handlers.set(type,handlers);}removeEventListener(type,handler){this.handlers.get(type)?.delete(handler);}emit(type,event={}){for(const handler of this.handlers.get(type)??[])handler({preventDefault(){},repeat:false,ctrlKey:false,altKey:false,metaKey:false,...event});}count(){return[...this.handlers.values()].reduce((sum,handlers)=>sum+handlers.size,0);}}const target=new Target(),input=new InputManager({target,bindings:INPUT_PROFILES.azerty});let interactions=0,releases=0;input.onPress(INPUT_ACTIONS.INTERACT,()=>interactions++);input.onRelease(INPUT_ACTIONS.MOVE_FORWARD,()=>releases++);target.emit("keydown",{code:"KeyE"});target.emit("keydown",{code:"KeyE",repeat:true});assert(interactions===1,"répétition automatique non ignorée");target.emit("keyup",{code:"KeyE"});target.emit("keydown",{code:"KeyW"});target.emit("keydown",{code:"ArrowUp"});target.emit("keyup",{code:"KeyW"});assert(input.isActive(INPUT_ACTIONS.MOVE_FORWARD),"action relâchée malgré une seconde touche");target.emit("keyup",{code:"ArrowUp"});assert(!input.isActive(INPUT_ACTIONS.MOVE_FORWARD)&&releases===1,"relâchement multiple incorrect");input.activate(INPUT_ACTIONS.MOVE_LEFT,"mobile:left");assert(input.isActive(INPUT_ACTIONS.MOVE_LEFT),"commande tactile inactive");input.deactivate(INPUT_ACTIONS.MOVE_LEFT,"mobile:left");assert(!input.isActive(INPUT_ACTIONS.MOVE_LEFT),"commande tactile bloquée");input.setEnabled(false);target.emit("keydown",{code:"KeyE"});assert(interactions===1,"action déclenchée pendant la pause");input.setEnabled(true);input.setBindings(INPUT_PROFILES.qwerty);target.emit("keydown",{code:"KeyZ"});assert(!input.isActive(INPUT_ACTIONS.MOVE_FORWARD),"mauvaise position active après changement de profil");target.emit("keydown",{code:"KeyW"});assert(input.isActive(INPUT_ACTIONS.MOVE_FORWARD),"position physique W/Z inactive");target.emit("keyup",{code:"KeyW"});assert(isHoldInputAction(INPUT_ACTIONS.RUN)&&!isHoldInputAction(INPUT_ACTIONS.INTERACT),"types d’action incorrects");target.emit("keydown",{code:"KeyE",ctrlKey:true});assert(interactions===1,"raccourci navigateur intercepté");input.dispose();assert(target.count()===0,"écouteurs non nettoyés");target.emit("keydown",{code:"KeyE"});assert(interactions===1,"gestionnaire actif après destruction");});

test("préférences : profils, disposition, persistance, conflit et réinitialisation",()=>{class Storage{constructor(){this.values=new Map();}getItem(key){return this.values.get(key)??null;}setItem(key,value){this.values.set(key,String(value));}removeItem(key){this.values.delete(key);}}const storage=new Storage();let preferences=selectInputProfile("qwerty",storage);assert(preferences.profile==="qwerty"&&preferences.layout==="qwerty"&&preferences.bindings[INPUT_ACTIONS.MOVE_FORWARD][0]==="KeyW","profil QWERTY non appliqué");preferences=loadInputPreferences(storage);assert(preferences.source==="storage"&&preferences.profile==="qwerty","préférences non rechargées");let remap=remapInputBinding(preferences,INPUT_ACTIONS.EXAMINE,"KeyE",{storage});assert(!remap.changed&&remap.conflict.action===INPUT_ACTIONS.INTERACT,"conflit non demandé");remap=remapInputBinding(preferences,INPUT_ACTIONS.EXAMINE,"KeyE",{replaceConflict:true,storage});assert(remap.changed&&remap.preferences.profile==="custom"&&remap.preferences.layout==="qwerty","disposition perdue après personnalisation");assert(remap.preferences.bindings[INPUT_ACTIONS.EXAMINE][0]==="KeyE"&&remap.preferences.bindings[INPUT_ACTIONS.INTERACT][0]==="KeyF","touches non échangées");assert(loadInputPreferences(storage).bindings[INPUT_ACTIONS.EXAMINE][0]==="KeyE","personnalisation non persistée");storage.setItem(INPUT_STORAGE_KEY,"{invalide");preferences=loadInputPreferences(storage);assert(preferences.recovered&&preferences.profile==="azerty"&&preferences.layout==="azerty","sauvegarde corrompue non restaurée");preferences=resetInputPreferences("qwerty",storage);assert(preferences.profile==="qwerty"&&preferences.layout==="qwerty"&&validateInputBindings(preferences.bindings).valid,"réinitialisation invalide");});

test("souris : boutons latéraux remappables et navigation bloquée",()=>{class Target{constructor(){this.handlers=new Map();}addEventListener(type,handler){const list=this.handlers.get(type)??new Set();list.add(handler);this.handlers.set(type,list);}removeEventListener(type,handler){this.handlers.get(type)?.delete(handler);}emit(type,event){for(const handler of this.handlers.get(type)??[])handler(event);}}const bindings=cloneInputBindings("azerty");bindings[INPUT_ACTIONS.EXAMINE]=["MouseBack"];const target=new Target(),input=new InputManager({target,bindings});let pressed=0,released=0,prevented=0,stopped=0;input.onPress(INPUT_ACTIONS.EXAMINE,()=>pressed++);input.onRelease(INPUT_ACTIONS.EXAMINE,()=>released++);const event=button=>({button,preventDefault(){prevented++;},stopImmediatePropagation(){stopped++;}});target.emit("mousedown",event(3));target.emit("mouseup",event(3));target.emit("auxclick",event(4));assert(pressed===1&&released===1,"bouton latéral non résolu");assert(prevented===3&&stopped===3,"navigation navigateur non bloquée");assert(pointerEventInputCode({button:3})==="MouseBack"&&pointerEventInputCode({button:4})==="MouseForward"&&formatInputCode("MouseBack")==="SOURIS 4","libellé souris invalide");input.dispose();});

