test("restauration : createGame expose un export réutilisable",()=>{const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(source.includes("function createGame(initialSave=null)")&&source.includes("migrateExplorationSave(initialSave)"),"entrée de restauration absente");assert(source.includes("cleanup.exportSave=exportGameState")&&source.includes("inventory:inventory.map(snapshotItem)"),"export de partie absent");assert(source.includes("resolveRestoredPlayerPosition")&&source.includes("levelObjectStates.set(Number(level)"),"position ou objets non restaurés");});

test("stockage de partie : écriture, lecture et suppression validées",()=>{class Storage{constructor(){this.values=new Map();}getItem(key){return this.values.get(key)??null;}setItem(key,value){this.values.set(key,String(value));}removeItem(key){this.values.delete(key);}}const raw=new Storage(),storage=createExplorationSaveStorage({storage:raw}),save=createExplorationSave({seed:777});assert(storage.read().status==="empty","stockage neuf non vide");assert(storage.write(save).ok,"écriture refusée");const loaded=storage.read();assert(loaded.ok&&loaded.save.world.seed===777,"lecture invalide");assert(storage.remove().ok&&storage.read().status==="empty","suppression invalide");});

test("stockage de partie : indisponibilité et corruption ne bloquent jamais",()=>{const unavailable=createExplorationSaveStorage({storage:{getItem(){throw new Error("private");},setItem(){throw new Error("quota");},removeItem(){throw new Error("private");}}});assert(!unavailable.read().ok&&!unavailable.write(createExplorationSave({seed:1})).ok&&!unavailable.remove().ok,"erreur de stockage propagée");const corrupt=createExplorationSaveStorage({storage:{getItem(){return "{cassé";},setItem(){},removeItem(){}}});assert(corrupt.read().status==="invalid","sauvegarde corrompue acceptée");});

test("migration : format legacy sauvegardé avant conversion v2",()=>{class Storage{constructor(raw){this.values=new Map([[SAVE_STORAGE_KEY,raw]]);}getItem(key){return this.values.get(key)??null;}setItem(key,value){this.values.set(key,String(value));}removeItem(key){this.values.delete(key);}}const level=createEmptyLevelSave(),legacy={version:0,seed:2468,level:2,elapsed:91,player:{position:[4,1.7,5],yaw:.4,pitch:0,thirst:12,hunger:8},inventory:[],progress:{exitOpened:false},levels:{1:level},savedAt:5000},raw=JSON.stringify(legacy),native=new Storage(raw),storage=createExplorationSaveStorage({storage:native}),result=storage.read();assert(result.ok&&result.status==="migrated"&&result.fromVersion===0,"migration v0 non exécutée");assert(result.save.version===2&&result.save.world.seed===2468&&result.save.world.level===2,"données legacy perdues");assert(native.getItem(SAVE_BACKUP_KEY)===raw&&storage.readBackup().raw===raw,"copie de secours absente");assert(JSON.parse(native.getItem(SAVE_STORAGE_KEY)).version===2,"format courant non réécrit");});

test("migration v1 : ancienne clé découverte sans route inventée",()=>{const current=createExplorationSave({seed:8642,level:3,elapsed:777,progress:{exitOpened:true,guide:{active:false,phase:"completed",level:2,position:[0,1.78,0],completedLevels:[1,2]}},levels:{1:createEmptyLevelSave()}}),legacy=structuredClone(current);legacy.version=1;delete legacy.journal;const raw=JSON.stringify(legacy),values=new Map([["backrooms.save.v1",raw]]),storage=createExplorationSaveStorage({storage:{getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,String(value)),removeItem:key=>values.delete(key)}}),result=storage.read();assert(result.ok&&result.status==="migrated"&&result.fromVersion===1&&result.sourceKey==="backrooms.save.v1","ancienne clé v1 non découverte");assert(result.save.version===2&&result.save.journal.coverage==="partial"&&result.save.journal.visitedLevels.length===1&&result.save.journal.visitedLevels[0].level===3,"journal v1 inventé ou incomplet");assert(result.save.journal.milestones.some(entry=>entry.id==="guide-complete:1")&&values.get(SAVE_BACKUP_KEY)===raw&&values.has(SAVE_STORAGE_KEY),"jalons ou sauvegarde de secours perdus");storage.remove();assert(!values.has(SAVE_STORAGE_KEY)&&!values.has("backrooms.save.v1"),"ancienne sauvegarde ressuscitable après suppression");});

test("migration : version inconnue conservée et signalée",()=>{const raw=JSON.stringify({version:99,secret:"future"}),values=new Map([[SAVE_STORAGE_KEY,raw]]),storage=createExplorationSaveStorage({storage:{getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,String(value)),removeItem:key=>values.delete(key)}}),result=storage.read();assert(!result.ok&&result.status==="incompatible"&&result.version===99,"version future non signalée");assert(values.get(SAVE_STORAGE_KEY)===raw&&!values.has(SAVE_BACKUP_KEY),"version inconnue modifiée");});

test("reprise complète : progression multi-niveaux conservée",()=>{const item=(type,id,level)=>({type,userData:{type,instanceId:id,level,powered:type==="plush",fried:false},position:[level,.2,level*2],rotation:[0,0,0,"XYZ"],scale:[1,1,1]}),one=createEmptyLevelSave(),two=createEmptyLevelSave(),three=createEmptyLevelSave();one.objects=[item("water_half","water-1",1)];one.consumed=["battery-1"];two.objects=[item("book","book-2",2)];two.doors=[{id:"door-2-3",angle:1.2}];three.objects=[item("artifact","artifact-3",3)];three.events=[{id:"arrival",done:true}];const original=createExplorationSave({seed:654321,level:3,elapsed:1842,position:[17,1.7,44],yaw:2.1,pitch:-.2,thirst:61,hunger:37,inventory:[item("plush","rabbit-1",1)],progress:{exitOpened:true,doors:[{sourceLevel:2,targetLevel:3,angle:1.2}],transitions:[{id:"hidden-exit",enabled:true}],guide:{active:false,phase:"waitLevel",level:2,position:[4,.2,8]},artifacts:[item("artifact","artifact-global",1)]},levels:{1:one,2:two,3:three},createdAt:10,updatedAt:20}),restored=parseExplorationSave(serializeExplorationSave(original));assert(restored.world.level===3&&restored.world.elapsed===1842&&restored.player.needs.hunger===37,"joueur multi-niveaux perdu");assert(restored.inventory[0].userData.instanceId==="rabbit-1"&&restored.levels[1].consumed[0]==="battery-1","inventaire ou consommation perdu");assert(restored.progress.exitOpened&&restored.progress.doors[0].angle===1.2&&restored.progress.guide.phase==="waitLevel","porte, sortie ou guide perdu");assert(restored.levels[3].events[0].done&&restored.progress.artifacts.length===1,"événement ou artefact perdu");});

test("reprise répétée : aucun objet restauré n’est partagé ou dupliqué",()=>{const snapshot=(id,x)=>({type:"book_red",userData:{type:"book_red",instanceId:id,level:2},position:[x,.1,2],rotation:[0,0,0,"XYZ"],scale:[1,1,1]}),save=createExplorationSave({seed:99,inventory:[snapshot("inventory-book",1)],levels:{2:{...createEmptyLevelSave(),objects:[snapshot("ground-book",3)]}}});for(let cycle=0;cycle<20;cycle++){const parsed=parseExplorationSave(serializeExplorationSave(save)),inventory=parsed.inventory.map(restoreItem),ground=parsed.levels[2].objects.map(restoreItem),ids=[...inventory,...ground].map(object=>object.userData.instanceId);assert(ids.length===2&&new Set(ids).size===2,"objet dupliqué après reprise");assert(inventory[0]!==ground[0]&&inventory[0].geometry!==ground[0].geometry,"ressource Three.js partagée entre restaurations");inventory.forEach(disposeObjectTree);ground.forEach(disposeObjectTree);}});

test("guide et artefacts : identité, disparition et persistance par niveau",()=>{const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8"),save=createExplorationSave({seed:15,progress:{guide:{active:false,phase:"completed",level:2,position:[1,.2,2],completedLevels:[1,2]}}}),restored=parseExplorationSave(serializeExplorationSave(save));assert(restored.progress.guide.completedLevels.join(",")==="1,2","niveaux terminés du guide perdus");assert(source.includes('id=`level-${level}:guide-artifact`'),"identité d’artefact non liée au niveau");assert(source.includes("guideCompletedLevels.add(level)")&&source.includes('guideActive=false;guidePhase="completed"'),"guide terminé encore actif");assert(source.includes("!guideCompletedLevels.has(enteredLevel)")&&source.includes('guidePhase=guideCompletedLevels.has(enteredLevel)?"completed":"inactive"'),"guide recréé au retour");assert(source.includes("const artifactIndex=artifacts.indexOf(object);if(artifactIndex>=0)artifacts.splice")&&source.includes("artifact.parent===scene"),"artefact ramassé encore animé au sol");assert(!source.includes("Math.hypot(camera.position.x-artifact.position.x"),"artefact supprimé par distance");});

test("fin du guide niveau 1 : mur intact, descente au seuil et artefact au pied",()=>{const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(source.includes('guidePhase="finish"')&&source.includes("chunk.originZ+chunk.worldLength-.55"),"approche finale du faux mur absente");assert(source.includes('else if(guidePhase==="finish")')&&source.includes("beginGuideCompletion(now)"),"disparition déclenchée avant l’arrivée au mur");assert(source.includes("createArtifact(companion.position)"),"artefact non déposé à la position finale du guide");assert(source.includes("exitOpened?chunk.walls.filter(mesh=>mesh!==exitWall):chunk.walls"),"faux mur encore bloquant après le guide");assert(!source.includes("exitWall.position.y=")&&!source.includes("exitWall.parent?.remove(exitWall)"),"faux mur déplacé ou supprimé");});

test("guide niveau 2 : apparition dans une position libre ou attente",()=>{const origin={x:5,z:5},blocked=(x,z)=>x>5,inside=(x,z)=>x>=0&&x<=10&&z>=0&&z<=10,spawn=findSafeGuideSpawn(origin,{collides:blocked,contains:inside,minDistance:1,maxDistance:2,ringStep:.5,samples:16,startAngle:0});assert(spawn&&inside(spawn.x,spawn.z)&&!blocked(spawn.x,spawn.z),"position sûre non trouvée");assert(Math.hypot(spawn.x-origin.x,spawn.z-origin.z)>=1,"guide trop proche du joueur");assert(findSafeGuideSpawn(origin,{collides:()=>true,contains:inside,minDistance:1,maxDistance:1,samples:8})===null,"apparition forcée dans un mur");const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");assert(source.includes("const spawn=safeGuideSpawn();if(!spawn){rebirthAt=now+250;}"),"nouvelle tentative sûre absente");});

test("i18n : langues, repli, notification et traduction du document",()=>{assert(LOCALE_STORAGE_KEY==="backrooms.locale.v1"&&SUPPORTED_LOCALES.join(",")==="fr,en","configuration i18n invalide");let notified=0;const unsubscribe=subscribeLocale(()=>notified++);setLocale("fr",{persist:false});assert(getLocale()==="fr"&&translate("language.label")==="Langue","français indisponible");setLocale("en",{persist:false});assert(getLocale()==="en"&&translate("language.label")==="Language"&&notified===1,"anglais ou notification indisponible");assert(translate("missing.translation.key")==="missing.translation.key","repli de clé instable");const textNode={dataset:{i18n:"language.label"},textContent:""},ariaNode={dataset:{i18nAria:"language.label"},setAttribute(name,value){this[name]=value;}},frButton={dataset:{locale:"fr"},classList:{toggle(name,value){this.active=value;}}},enButton={dataset:{locale:"en"},classList:{toggle(name,value){this.active=value;}}},root={documentElement:{lang:""},querySelectorAll(selector){return selector==="[data-i18n]"?[textNode]:selector==="[data-i18n-aria]"?[ariaNode]:selector==="[data-locale]"?[frButton,enButton]:[];}};translateDocument(root);assert(root.documentElement.lang==="en"&&textNode.textContent==="Language"&&ariaNode["aria-label"]==="Language"&&!frButton.classList.active&&enButton.classList.active,"document non traduit");unsubscribe();setLocale("fr",{persist:false});});

test("i18n objets : clés stables et anciennes sauvegardes retraduites",()=>{setLocale("en",{persist:false});const legacy=createItem("plush",{userData:{name:"PELUCHE USÉE",description:"Ancien texte français",powered:true}});assert(legacy.userData.name==="POWERED PLUSH"&&legacy.userData.nameKey==="item.plush.poweredName","ancien texte non remplacé");const snapshot=snapshotItem(legacy);assert(!("name" in snapshot.userData)&&!("description" in snapshot.userData),"texte traduit encore persisté");const restored=restoreItem(snapshot);assert(restored.userData.name==="POWERED PLUSH"&&restored.userData.descriptionKey==="item.plush.poweredDescription","objet restauré non traduit");disposeObjectTree(legacy);disposeObjectTree(restored);setLocale("fr",{persist:false});});

