test("reportage v1 : faits confirmés sans historique inventé",()=>{const water=createItem("water_half",{userData:{instanceId:"level-1:water_half:0",level:1,sips:1}}),artifactOne=createItem("artifact",{userData:{instanceId:"level-1:guide-artifact",level:1,guideReward:true}}),artifactTwo=createItem("artifact",{userData:{instanceId:"level-2:guide-artifact",level:2,guideReward:true}}),save=createExplorationSave({seed:737373,level:2,elapsed:321,thirst:34,hunger:21,inventory:[snapshotItem(water),snapshotItem(artifactOne),snapshotItem(artifactTwo)],progress:{exitOpened:true,doors:[{sourceLevel:2,targetLevel:3,angle:.5}],guide:{active:false,phase:"completed",level:2,position:[0,1.78,0],completedLevels:[1,2]}},levels:{1:createEmptyLevelSave(),2:createEmptyLevelSave()}}),report=buildSaveReport(save);assert(report?.coverage==="partial"&&report.subject.level===2&&report.inventory.length===3,"rapport v1 incomplet");assert(report.resources.waterSips===1&&report.resources.artifacts===2,"ressources incorrectes");assert(report.milestones.some(entry=>entry.id==="guide-complete:1")&&report.milestones.some(entry=>entry.id==="exit-opened:1"),"étapes confirmées absentes");assert(report.route.length===1&&report.route[0].level===2&&report.encounters.length===0&&!report.sections.encounters,"historique inventé");assert(report.inventory.filter(item=>item.type==="artifact").map(item=>item.instanceId).join(",")==="level-1:guide-artifact,level-2:guide-artifact","artefacts confondus");disposeObjectTree(water);disposeObjectTree(artifactOne);disposeObjectTree(artifactTwo);});

