test("reportage accueil : section conditionnelle, rubriques sûres et actualisation",()=>{const html=readFileSync(new URL("../index.html",import.meta.url),"utf8"),source=readFileSync(new URL("../js/landing.js",import.meta.url),"utf8");assert(/id="exploration-report"[^>]*hidden/.test(html),"reportage visible par défaut");for(const section of["inventory","route","milestones","encounters","resources"])assert(html.includes(`data-report-section="${section}" hidden`),`rubrique ${section} visible sans données`);assert(source.includes("readSaveReport()")&&source.includes("reportSection.hidden=true")&&source.includes("reportSection.hidden=false"),"visibilité non reliée à la sauvegarde");for(const unavailable of["route-history","encounter-history","resource-history"])assert(source.includes(`unavailable.includes("${unavailable}")`),`historique indisponible exposé : ${unavailable}`);assert(source.includes('addEventListener("storage"')&&source.includes('addEventListener("backrooms:save-changed"'),"actualisation du reportage absente");assert(source.includes("textContent=String(text)")&&!source.includes("report.subject.position")&&!source.includes("report.subject.orientation"),"données techniques ou HTML brut exposés");});

