test("reportage robuste : stockage indisponible, JSON corrompu et version future masqués",()=>{const unavailable=readSaveReport({read:()=>({ok:false,status:"unavailable",save:null})}),corruptValues=new Map([[SAVE_STORAGE_KEY,"{cassé"]]),futureValues=new Map([[SAVE_STORAGE_KEY,JSON.stringify({version:999})]]),native=values=>({getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,String(value)),removeItem:key=>values.delete(key)}),corrupt=readSaveReport(createExplorationSaveStorage({storage:native(corruptValues)})),future=readSaveReport(createExplorationSaveStorage({storage:native(futureValues)}));assert(!unavailable.available&&unavailable.status==="unavailable","stockage indisponible affiché");assert(!corrupt.available&&corrupt.status==="invalid","JSON corrompu affiché");assert(!future.available&&future.status==="incompatible","version future affichée");});

test("reportage complet : objets identiques distincts, retours, rencontres et bouteilles partielles",()=>{const objects=[createItem("book_red",{userData:{instanceId:"book-l1",level:1}}),createItem("book_red",{userData:{instanceId:"book-l2",level:2}}),createItem("water_full",{userData:{instanceId:"water-a",level:1,sips:3}}),createItem("water_half",{userData:{instanceId:"water-b",level:2,sips:1}})],save=createExplorationSave({seed:8181,level:2,inventory:objects.map(snapshotItem),journal:{coverage:"complete",visitedLevels:[{level:1,firstVisitedAt:0,entries:2},{level:2,firstVisitedAt:30,entries:1}],transitions:[{id:"go",source:1,target:2,elapsed:30},{id:"back",source:2,target:1,elapsed:45}],milestones:[{id:"known",type:"guide-awake",level:1,elapsed:10}],resources:{water_full:{taken:1}},encounters:{watcher:{spawned:3,observed:2,chased:1,vanished:2,levels:{2:3}}}}}),report=buildSaveReport(save);assert(report.inventory.length===4&&report.inventory.filter(item=>item.type==="book_red").length===2,"objets de niveaux différents fusionnés");assert(report.resources.waterSips===4,"gorgées partielles incorrectes");assert(report.route[0].entries===2&&report.transitions.length===2&&report.encounters[0].observed===2,"retours ou rencontres perdus");objects.forEach(disposeObjectTree);});

test("journal longue session : toutes les collections restent bornées",()=>{const journal=new ExplorationJournal();for(let index=1;index<=400;index++){journal.visitLevel(index,index).crossTransition(`transition-${index}`,index,index+1,index);journal.completeMilestone(`milestone-${index}`,index,index,{type:"generic"});journal.recordResource(`resource-${index}`,"taken",1,index);journal.recordEncounter(`creature-${index}`,"spawned",index,index);}const snapshot=journal.snapshot();assert(snapshot.visitedLevels.length===JOURNAL_LIMITS.visitedLevels,"visites non bornées");assert(snapshot.transitions.length===JOURNAL_LIMITS.transitions&&snapshot.milestones.length===JOURNAL_LIMITS.milestones,"chronologie non bornée");assert(Object.keys(snapshot.resources).length===JOURNAL_LIMITS.resourceTypes&&Object.keys(snapshot.encounters).length===JOURNAL_LIMITS.encounterTypes,"registres non bornés");});

test("reportage confidentiel : aucune coordonnée, métadonnée ou étape future n’est publiée",()=>{const source=readFileSync(new URL("../js/landing.js",import.meta.url),"utf8"),gameSource=readFileSync(new URL("../js/game.js",import.meta.url),"utf8"),styles=readFileSync(new URL("../assets/styles.css",import.meta.url),"utf8");for(const forbidden of["report.subject.position","report.subject.orientation","entry.metadata","JSON.stringify(report)"])assert(!source.includes(forbidden),`donnée interne rendue : ${forbidden}`);assert(source.includes('translated===key?translate("report.milestone.generic")'),"jalon inconnu révélateur");assert(gameSource.includes('saveStorage.remove();refreshSaveUi()')&&gameSource.includes('new CustomEvent("backrooms:save-changed")'),"suppression non répercutée immédiatement");assert(styles.includes("@media(max-width:750px)")&&styles.includes(".report-grid{grid-template-columns:1fr}"),"mise en page mobile absente");});

test("journal d’exploration : visites, événements uniques, ressources et rencontres",()=>{const journal=new ExplorationJournal();journal.visitLevel(2,12).visitLevel(1,18).visitLevel(2,24).crossTransition("hidden-exit",1,2,12).recordResource("water_full","taken",1,1).recordResource("water_full","consumed",2,2).recordEncounter("watcher","spawned",2,30).recordEncounter("watcher","observed",2,32);assert(journal.completeMilestone("guide-complete:1",1,40,{type:"guide-complete"}),"jalon initial refusé");assert(!journal.completeMilestone("guide-complete:1",1,41,{type:"guide-complete"}),"jalon unique dupliqué");const snapshot=journal.snapshot(),levelTwo=snapshot.visitedLevels.find(entry=>entry.level===2);assert(snapshot.coverage==="complete"&&levelTwo.entries===2&&snapshot.transitions[0].source===1&&snapshot.transitions[0].target===2,"route non enregistrée");assert(snapshot.resources.water_full.taken===1&&snapshot.resources.water_full.consumed===2,"ressources non comptées");assert(snapshot.encounters.watcher.spawned===1&&snapshot.encounters.watcher.observed===1&&snapshot.milestones.length===1,"rencontres ou jalons incorrects");const restored=new ExplorationJournal(snapshot).snapshot();assert(JSON.stringify(restored)===JSON.stringify(snapshot),"journal non restaurable à l’identique");});

test("instrumentation : jeu et créatures publient les événements du reportage",()=>{const gameSource=readFileSync(new URL("../js/game.js",import.meta.url),"utf8"),creatureSource=readFileSync(new URL("../js/systems/creature-registry.js",import.meta.url),"utf8");for(const hook of["recordResource","completeMilestone","crossTransition","visitLevel","recordEncounter"])assert(gameSource.includes(hook),`hook de journal absent : ${hook}`);for(const event of['event:"spawned"','event:"observed"','event:"chased"'])assert(creatureSource.includes(event),`événement créature absent : ${event}`);assert(creatureSource.includes("event:reason")&&creatureSource.includes('#remove(index,"vanished"'),"disparition de créature absente");assert(creatureSource.includes('{notify:false}'),"déchargement de carte compté comme rencontre");});

test("sauvegarde automatique : attente, intervalle, immédiat et nettoyage",()=>{let writes=0,tick=null,cleared=false;const storage={write(save){writes++;return{ok:true,status:"saved",updatedAt:save.meta.updatedAt};}},controller=new AutosaveController({snapshot:()=>createExplorationSave({seed:123}),storage,intervalMs:5000,setIntervalFn:callback=>{tick=callback;return 9;},clearIntervalFn:id=>{cleared=id===9;}});assert(controller.flush().status==="not-ready","écriture avant restauration");controller.start();assert(writes===0&&typeof tick==="function","intervalle non préparé");tick();assert(writes===1,"premier intervalle non sauvegardé");tick();assert(writes===1,"état propre réécrit");controller.markDirty({reason:"item",immediate:true});assert(writes===2,"modification importante non sauvegardée");controller.markDirty({immediate:false});controller.stop({flush:true});assert(writes===3&&cleared&&!controller.ready,"arrêt ou vidage invalide");});

test("sauvegarde automatique : hooks importants présents dans le jeu",()=>{const source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8");for(const hook of["take-item","combine","power-plush","drop-item","drink","level-change","before-unload","return-home"])assert(source.includes(hook),`hook absent : ${hook}`);assert(source.includes("intervalMs:15000")&&source.includes("autosave?.stop()"),"intervalle ou nettoyage absent");});

test("interface de sauvegarde : continuer, résumé, pause et confirmations",()=>{const html=readFileSync(new URL("../index.html",import.meta.url),"utf8"),source=readFileSync(new URL("../js/game.js",import.meta.url),"utf8"),styles=readFileSync(new URL("../assets/controls.css",import.meta.url),"utf8");for(const id of["continue-game","delete-save","save-summary","pause-save","pause-load","save-status"])assert(html.includes(`id="${id}"`),`élément absent : ${id}`);assert(html.includes('id="continue-game" class="play-button continue-button" type="button" hidden')&&styles.includes(".continue-button[hidden]{display:none}"),"bouton Continuer visible sans sauvegarde");assert(source.includes("function refreshSaveUi()")&&source.includes('t("game.save.summary"')&&source.includes("save.meta.updatedAt"),"résumé non révélateur absent");assert(source.includes("startGame(result.save)")&&source.includes("createGame(result.save)"),"reprise accueil ou pause absente");for(const key of["game.save.confirmNew","game.save.confirmDelete","game.save.confirmLoad"])assert(source.includes(key),`confirmation traduisible absente : ${key}`);assert(source.includes('event.code!=="Escape"||!paused||pauseMenu.hidden')&&source.includes('[globalThis,"keydown",pauseEscape]'),"fermeture de pause avec Échap absente ou non nettoyée");});

test("commandes complètes : chaque action répond dans les deux profils",()=>{class Target{constructor(){this.handlers=new Map();}addEventListener(type,handler){const list=this.handlers.get(type)??new Set();list.add(handler);this.handlers.set(type,list);}removeEventListener(type,handler){this.handlers.get(type)?.delete(handler);}emit(type,event={}){for(const handler of this.handlers.get(type)??[])handler({preventDefault(){},repeat:false,ctrlKey:false,altKey:false,metaKey:false,...event});}}for(const profile of["azerty","qwerty"]){const target=new Target(),input=new InputManager({target,bindings:INPUT_PROFILES[profile]}),pressed=new Set(),released=new Set();for(const action of INPUT_CATALOG){input.onPress(action.id,()=>pressed.add(action.id));input.onRelease(action.id,()=>released.add(action.id));const code=INPUT_PROFILES[profile][action.id][0],key=code.startsWith("Key")?code.slice(3).toLowerCase():code.startsWith("Digit")?code.slice(5):undefined;target.emit("keydown",{code,key});target.emit("keyup",{code,key});}assert(pressed.size===INPUT_CATALOG.length,`actions manquantes en ${profile}`);assert(released.size===INPUT_CATALOG.length,`relâchements manquants en ${profile}`);input.dispose();}});

test("remappage complet : douze commandes personnalisées persistent",()=>{class Storage{constructor(){this.values=new Map();}getItem(key){return this.values.get(key)??null;}setItem(key,value){this.values.set(key,String(value));}}const storage=new Storage(),codes=["Numpad0","Numpad1","Numpad2","Numpad3","Numpad4","Numpad5","Numpad6","Numpad7","Numpad8","Numpad9","Home","End"];let preferences=selectInputProfile("qwerty",storage);INPUT_CATALOG.forEach((action,index)=>{const result=remapInputBinding(preferences,action.id,codes[index],{storage});assert(result.changed,`remappage refusé : ${action.id}`);preferences=result.preferences;});const restored=loadInputPreferences(storage);assert(restored.profile==="custom"&&restored.layout==="qwerty","profil personnalisé perdu");INPUT_CATALOG.forEach((action,index)=>assert(restored.bindings[action.id][0]===codes[index],`touche non persistée : ${action.id}`));assert(validateInputBindings(restored.bindings).valid,"configuration complète invalide");const reset=selectInputProfile("azerty",storage);assert(reset.profile==="azerty"&&reset.bindings[INPUT_ACTIONS.MOVE_FORWARD][0]==="KeyZ","changement de profil après personnalisation invalide");});

test("stockage indisponible : les commandes restent utilisables en mémoire",()=>{const storage={getItem(){throw new Error("accès interdit");},setItem(){throw new Error("quota");}},loaded=loadInputPreferences(storage);assert(loaded.profile==="azerty"&&validateInputBindings(loaded.bindings).valid,"repli de lecture invalide");const selected=selectInputProfile("qwerty",storage);assert(selected.profile==="qwerty"&&selected.source==="memory"&&validateInputBindings(selected.bindings).valid,"repli d’écriture invalide");});

test("cycle des inputs : aucune écoute ni action ne survit à la destruction",()=>{class Target{constructor(){this.handlers=new Map();}addEventListener(type,handler){const list=this.handlers.get(type)??new Set();list.add(handler);this.handlers.set(type,list);}removeEventListener(type,handler){this.handlers.get(type)?.delete(handler);}count(){return[...this.handlers.values()].reduce((sum,list)=>sum+list.size,0);}}const target=new Target();for(let index=0;index<30;index++){const input=new InputManager({target,bindings:index%2?INPUT_PROFILES.azerty:INPUT_PROFILES.qwerty});input.activate(INPUT_ACTIONS.RUN,"test");input.dispose();assert(target.count()===0,"écouteur accumulé après destruction");assert(!input.isActive(INPUT_ACTIONS.RUN),"action maintenue après destruction");}});

test("libellés spéciaux : les noms longs restent explicites",()=>{for(const[code,label]of [["Space","ESPACE"],["Enter","ENTRÉE"],["ShiftLeft","MAJ"],["ControlRight","CTRL"],["MouseForward","SOURIS 5"]])assert(formatInputCode(code)===label,`libellé incorrect pour ${code}`);});

audio.stop();
let debugImports=0;
const normalDebugSession=await loadOptionalDebug(Object.freeze({}),{search:"",importer:async()=>{debugImports++;throw new Error("import inattendu");}});
assert(!normalDebugSession.requested&&!normalDebugSession.loaded&&debugImports===0,"le mode normal tente de charger debug");
console.log("✓ jeu normal : aucun chargement du dossier debug");
let unavailableReported=false;
const missingDebugSession=await loadOptionalDebug(Object.freeze({}),{search:"?debug=1",importer:async()=>{debugImports++;throw new Error("404 debug/debug.js");},onUnavailable:()=>unavailableReported=true});
assert(missingDebugSession.requested&&!missingDebugSession.loaded&&unavailableReported&&debugImports===1,"module debug absent non contenu");
missingDebugSession.dispose();
console.log("✓ production ?debug=1 : module absent sans blocage");
console.log("\n69 scénarios de parcours et 2 scénarios d’absence debug validés.");
